def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remainder = bins % item
    closest_diff = np.minimum(remainder, item - remainder)
    return np.where(fit_mask, -closest_diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining > 0, 1.0 / remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
